package org.sleepwell.app;
import android.content.Context;import android.app.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.function.*;
/** A category action opens an owned radio selector; selection applies once, Cancel does not. */
final class SoundCategoryPicker {
 static Dialog show(Activity owner,String selected,boolean night,ToIntFunction<String> count,Consumer<String> choose){List<String> keys=new ArrayList<>(SoundBrowseFilter.ALL);if(night)keys.add("favorites");String[] labels=new String[keys.size()];for(int n=0;n<labels.length;n++){String key=keys.get(n);labels[n]=SoundBrowseFilter.name(key)+" ("+count.applyAsInt(key)+")";}return SleepPicker.choices(owner,"Sound categories",labels,Math.max(0,keys.indexOf(selected)),index->choose.accept(keys.get(index)));}
 static LinearLayout quick(LinearLayout body,String selected,ToIntFunction<String> count,Consumer<String> choose){Context context=body.getContext();LinearLayout row=Design.row(context);row.setMinimumHeight(Design.dp(context,48));for(String key:List.of("all","snoring","speech")){String label=SoundBrowseFilter.name(key)+" ("+count.applyAsInt(key)+")";boolean active=key.equals(selected);TextView chip=Design.text(context,label,13,active?600:400,active?Design.CREAM:Design.INK);chip.setGravity(Gravity.CENTER);chip.setMinimumHeight(Design.dp(context,48));Design.pad(chip,6,6);chip.setBackground(Design.touch(context,active?Design.BROWN:Design.SOFT,12));chip.setSelected(active);chip.setContentDescription(label);chip.setFocusable(true);chip.setOnClickListener(v->choose.accept(key));LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(0,-1,1);if(row.getChildCount()>0)layout.leftMargin=Design.dp(context,8);row.addView(chip,layout);}body.addView(row,new LinearLayout.LayoutParams(-1,-2));return row;}
 static View header(LinearLayout row,Runnable open){row.setMinimumHeight(Design.dp(row.getContext(),52));android.view.ViewGroup.LayoutParams layout=row.getLayoutParams();layout.height=android.view.ViewGroup.LayoutParams.WRAP_CONTENT;row.setLayoutParams(layout);View button=Design.iconButton(row.getContext(),"fade","Filter sound categories",open);button.setBackground(Design.touch(row.getContext(),Design.SOFT,24));row.addView(button,new LinearLayout.LayoutParams(Design.dp(row.getContext(),48),Design.dp(row.getContext(),48)));return button;}
 static void selected(LinearLayout body,String key,int count,Runnable open){if(!SoundBrowseFilter.extended(key))return;View chip=RecordUi.chip(body.getContext(),SoundBrowseFilter.name(key)+" ("+count+")",true,open);chip.setContentDescription("Selected category: "+SoundBrowseFilter.name(key)+" ("+count+")");body.addView(chip);Design.space(body,6);}
 private SoundCategoryPicker(){}
}
